ci-print-zero-to-four.solutionCode:
stop = int(input())
for n in range(stop):
    print(n)

ci-even-under-ten.solutionCode:
stop = int(input())
for n in range(0, stop, 2):
    print(n)

ci-countdown-three-to-one.solutionCode:
start = int(input())
for n in range(start, 0, -1):
    print(n)

ci-print-squares-one-to-four.solutionCode:
n = int(input())
for value in range(1, n + 1):
    print(value * value)
